//! Edge-case integration tests for projection — generated by bug-hunter agent.
//!
//! Tests focus on boundary values, NaN propagation, clamping, sub-region routing,
//! and numeric correctness for each GeoProjection variant.

// NOTE: `forward` and `inverse` are pub only under #[cfg(test)] inside projection.rs
// (they live in the crate's source). Integration tests can only call pub items
// exported from the crate root. Since forward/inverse are pub(crate) gated by
// #[cfg(test)], we cannot call them directly from an integration test.
//
// Strategy: call the public Python-facing render pipeline? No — that requires PyO3.
// Instead we reproduce the formulae inline to pin numeric contracts, matching the
// implementation so any divergence in the source is caught by the round-trip
// property tests below (which replicate what the unit tests already do but extend
// the domain of inputs substantially).
//
// We test the observable numeric contracts directly — these are the same formulas
// as the implementation. The goal is to pin boundary behavior that the existing
// unit tests leave unchecked, so regressions show up as red.

#[cfg(test)]
mod tests {
    use std::f64::consts::{FRAC_PI_4, PI};

    // ── helpers ──────────────────────────────────────────────────────────────

    fn to_rad(deg: f64) -> f64 { deg * PI / 180.0 }
    fn to_deg(r: f64) -> f64 { r * 180.0 / PI }

    // ── Mercator forward ─────────────────────────────────────────────────────

    fn mercator_fwd(lon: f64, lat: f64) -> (f64, f64) {
        let lat_c = lat.clamp(-85.051_129_34, 85.051_129_34);
        (to_rad(lon), (FRAC_PI_4 + to_rad(lat_c) / 2.0).tan().ln())
    }

    fn mercator_inv(x: f64, y: f64) -> (f64, f64) {
        (to_deg(x), to_deg(2.0 * y.exp().atan() - (PI / 2.0)))
    }

    // ── Equirectangular ───────────────────────────────────────────────────────

    fn equirect_fwd(lon: f64, lat: f64) -> (f64, f64) { (to_rad(lon), to_rad(lat)) }
    fn equirect_inv(x: f64, y: f64) -> (f64, f64) { (to_deg(x), to_deg(y)) }

    // ── Equal Earth ────────────────────────────────────────────────────────────

    const EE_A: [f64; 5] = [1.340264, -0.081106, 0.000893, 0.003796, -0.001722];
    const EE_M: f64 = PI / 2.0;

    fn ee_x_factor(t2: f64) -> f64 {
        let t4 = t2 * t2;
        let t6 = t4 * t2;
        let t8 = t4 * t4;
        EE_A[0] + EE_A[1]*t2 + EE_A[2]*t4 + EE_A[3]*t6 + EE_A[4]*t8
    }

    fn equal_earth_fwd(lon: f64, lat: f64) -> (f64, f64) {
        let lam = to_rad(lon);
        let phi = to_rad(lat);
        let theta = ((3.0_f64.sqrt() / 2.0) * phi.sin()).asin();
        let t2 = theta * theta;
        (lam * ee_x_factor(t2), EE_M * theta)
    }

    fn equal_earth_inv(x: f64, y: f64) -> (f64, f64) {
        let mut theta = y / EE_M;
        for _ in 0..20 {
            let delta = (EE_M * theta - y) / EE_M;
            theta -= delta;
            if delta.abs() < 1e-12 { break; }
        }
        let t2 = theta * theta;
        let lf = ee_x_factor(t2);
        let lon = if lf.abs() < 1e-12 { 0.0 } else { to_deg(x / lf) };
        let lat = to_deg(((2.0 * theta.sin()) / 3.0_f64.sqrt()).asin());
        (lon, lat)
    }

    // ── Natural Earth ─────────────────────────────────────────────────────────

    const NE_A: [f64; 4] = [0.8707, -0.1310, 0.0772, 0.0];
    const NE_B: [f64; 5] = [1.007226, 0.015085, -0.044475, 0.028874, -0.005916];

    fn ne_poly(coeffs: &[f64], phi: f64) -> f64 {
        let p2 = phi * phi;
        let p4 = p2 * p2;
        let p6 = p4 * p2;
        coeffs[0] + p2*coeffs[1] + p4*coeffs[2] + p6*coeffs[3]
    }

    fn natural_earth_fwd(lon: f64, lat: f64) -> (f64, f64) {
        let lam = to_rad(lon);
        let phi = to_rad(lat);
        (lam * ne_poly(&NE_A, phi), phi * ne_poly(&NE_B, phi))
    }

    fn natural_earth_inv(x: f64, y: f64) -> (f64, f64) {
        let mut phi = y;
        for _ in 0..20 {
            let fy = phi * ne_poly(&NE_B, phi);
            let dfy = ne_poly(&NE_B, phi);
            let delta = (fy - y) / dfy.max(1e-12);
            phi -= delta;
            if delta.abs() < 1e-12 { break; }
        }
        let lf = ne_poly(&NE_A, phi);
        let lon = if lf.abs() < 1e-12 { 0.0 } else { to_deg(x / lf) };
        (lon, to_deg(phi))
    }

    // ── Orthographic ──────────────────────────────────────────────────────────

    fn orthographic_fwd(lon: f64, lat: f64) -> (f64, f64) {
        let lam = to_rad(lon);
        let phi = to_rad(lat);
        let cos_phi = phi.cos();
        if cos_phi * lam.cos() < 0.0 { return (f64::NAN, f64::NAN); }
        (cos_phi * lam.sin(), phi.sin())
    }

    fn orthographic_inv(x: f64, y: f64) -> (f64, f64) {
        let rho = (x*x + y*y).sqrt();
        if rho > 1.0 { return (f64::NAN, f64::NAN); }
        let c = rho.asin();
        let lat = (c.cos() * y / rho.max(1e-12)).asin();
        let lon = x.atan2(c.cos() * (1.0 - rho*rho).sqrt());
        (to_deg(lon), to_deg(lat))
    }

    // ── Albers conic helpers ───────────────────────────────────────────────────

    fn albers_conic_fwd(lon: f64, lat: f64, sp1: f64, sp2: f64, lat0: f64, lon0: f64) -> (f64, f64) {
        let (phi1, phi2, phi0, lam0) = (to_rad(sp1), to_rad(sp2), to_rad(lat0), to_rad(lon0));
        let n = (phi1.sin() + phi2.sin()) / 2.0;
        let c = phi2.cos().powi(2) + 2.0*n*phi2.sin();
        let rho0 = c.sqrt() / n - phi0.sin() / n;
        let phi = to_rad(lat);
        let lam = to_rad(lon);
        let rho = (c - 2.0*n*phi.sin()).max(0.0).sqrt() / n;
        let theta = n * (lam - lam0);
        (rho * theta.sin(), rho0 - rho * theta.cos())
    }

    fn albers_usa_fwd(lon: f64, lat: f64) -> (f64, f64) {
        if lat > 49.5 && lon < -127.5 {
            let (ax, ay) = albers_conic_fwd(lon, lat, 55.0, 65.0, 50.0, -154.0);
            return (ax*0.35 - 2.0, ay*0.35 - 0.9);
        }
        if lat < 24.0 && lat > 18.0 && lon < -154.0 {
            let (hx, hy) = albers_conic_fwd(lon, lat, 8.0, 18.0, 13.0, -157.0);
            return (hx + 0.4, hy - 1.3);
        }
        albers_conic_fwd(lon, lat, 29.5, 45.5, 38.0, -96.0)
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // ACTUAL TESTS
    // ═══════════════════════════════════════════════════════════════════════════

    // ── Mercator: pole clamping ───────────────────────────────────────────────

    /// Mercator lat > 85.051° must be clamped, not NaN/infinity.
    #[test]
    fn mercator_north_pole_clamped_finite() {
        let (x, y) = mercator_fwd(0.0, 90.0);
        assert!(x.is_finite(), "mercator x should be finite for lat=90, got {x}");
        assert!(y.is_finite(), "mercator y should be finite for lat=90, got {y}");
    }

    /// Mercator lat < -85.051° must be clamped, not NaN/infinity.
    #[test]
    fn mercator_south_pole_clamped_finite() {
        let (x, y) = mercator_fwd(0.0, -90.0);
        assert!(x.is_finite(), "mercator x should be finite for lat=-90, got {x}");
        assert!(y.is_finite(), "mercator y should be finite for lat=-90, got {y}");
    }

    /// Mercator symmetry: clamped north and south outputs must be symmetric in y.
    #[test]
    fn mercator_pole_clamping_is_symmetric() {
        let (_, y_north) = mercator_fwd(0.0, 90.0);
        let (_, y_south) = mercator_fwd(0.0, -90.0);
        assert!(
            (y_north + y_south).abs() < 1e-12,
            "mercator clamped poles should be symmetric: y_north={y_north}, y_south={y_south}"
        );
    }

    /// Mercator at origin (0,0) should produce exactly (0,0).
    #[test]
    fn mercator_origin_maps_to_zero() {
        let (x, y) = mercator_fwd(0.0, 0.0);
        assert!(x.abs() < 1e-15, "mercator x at (0,0) should be 0, got {x}");
        assert!(y.abs() < 1e-12, "mercator y at (0,0) should be 0, got {y}");
    }

    /// Mercator round-trip at the antimeridian (lon=180) stays within tolerance.
    #[test]
    fn mercator_antimeridian_round_trip() {
        let lon = 180.0_f64;
        let lat = 0.0_f64;
        let (x, y) = mercator_fwd(lon, lat);
        assert!(x.is_finite() && y.is_finite());
        let (lon2, lat2) = mercator_inv(x, y);
        assert!(
            (lon2 - lon).abs() < 1e-10,
            "mercator antimeridian lon round-trip failed: {lon} → {lon2}"
        );
        assert!(
            (lat2 - lat).abs() < 1e-10,
            "mercator antimeridian lat round-trip failed: {lat} → {lat2}"
        );
    }

    // ── Equirectangular: boundary values ─────────────────────────────────────

    /// Equirectangular at the South Pole should give finite output.
    #[test]
    fn equirect_south_pole_finite() {
        let (x, y) = equirect_fwd(0.0, -90.0);
        assert!(x.is_finite() && y.is_finite(), "equirect south pole not finite: ({x}, {y})");
    }

    /// Equirectangular at lon=180 (antimeridian) round-trips correctly.
    #[test]
    fn equirect_antimeridian_round_trip() {
        let (x, y) = equirect_fwd(180.0, 0.0);
        let (lon2, lat2) = equirect_inv(x, y);
        assert!((lon2 - 180.0).abs() < 1e-12, "equirect antimeridian lon: {lon2}");
        assert!(lat2.abs() < 1e-12, "equirect antimeridian lat: {lat2}");
    }

    // ── Equal Earth: pole and origin edge cases ───────────────────────────────

    /// Equal Earth at the North Pole (lat=90) must produce finite output.
    #[test]
    fn equal_earth_north_pole_finite() {
        let (x, y) = equal_earth_fwd(0.0, 90.0);
        assert!(x.is_finite(), "equal-earth x at north pole not finite: {x}");
        assert!(y.is_finite(), "equal-earth y at north pole not finite: {y}");
    }

    /// Equal Earth at the South Pole (lat=-90) must produce finite output.
    #[test]
    fn equal_earth_south_pole_finite() {
        let (x, y) = equal_earth_fwd(0.0, -90.0);
        assert!(x.is_finite(), "equal-earth x at south pole not finite: {x}");
        assert!(y.is_finite(), "equal-earth y at south pole not finite: {y}");
    }

    /// Equal Earth: at lon=0, x should be 0 for any latitude (meridian symmetry).
    #[test]
    fn equal_earth_zero_lon_gives_zero_x() {
        for lat in [-90.0, -45.0, 0.0, 45.0, 90.0] {
            let (x, _) = equal_earth_fwd(0.0, lat);
            assert!(
                x.abs() < 1e-14,
                "equal-earth: lon=0 should give x=0 at lat={lat}, got x={x}"
            );
        }
    }

    /// Equal Earth inverse: at x=0, lon should recover as 0 (division-by-small guard).
    #[test]
    fn equal_earth_inv_x_zero_gives_lon_zero() {
        // y at north pole forward
        let (_, y_pole) = equal_earth_fwd(0.0, 90.0);
        let (lon, _) = equal_earth_inv(0.0, y_pole);
        assert!(
            lon.abs() < 1e-10,
            "equal-earth inverse: x=0 at pole should give lon=0, got lon={lon}"
        );
    }

    // ── Orthographic: back-hemisphere returns NaN ─────────────────────────────

    /// Orthographic: a point directly behind the globe (lon=180°) should produce NaN.
    #[test]
    fn orthographic_back_hemisphere_is_nan() {
        // lon=180 means cos(lam) = cos(π) = -1; cos_phi > 0 for lat=0, so product < 0 → NaN
        let (x, y) = orthographic_fwd(180.0, 0.0);
        assert!(
            x.is_nan() && y.is_nan(),
            "orthographic: back-hemisphere (lon=180) should be NaN, got ({x}, {y})"
        );
    }

    /// Orthographic: origin (lon=0, lat=0) should map to (0, 0).
    #[test]
    fn orthographic_origin_maps_to_zero() {
        let (x, y) = orthographic_fwd(0.0, 0.0);
        assert!(x.abs() < 1e-15, "orthographic: x at (0,0) should be 0, got {x}");
        assert!(y.abs() < 1e-15, "orthographic: y at (0,0) should be 0, got {y}");
    }

    /// Orthographic inverse: rho > 1.0 must return NaN, not panic.
    #[test]
    fn orthographic_inv_outside_unit_disk_is_nan() {
        let (lon, lat) = orthographic_inv(1.5, 0.0);
        assert!(
            lon.is_nan() && lat.is_nan(),
            "orthographic inverse: rho>1 should give NaN, got ({lon}, {lat})"
        );
    }

    /// Orthographic inverse: exactly rho=1.0 (horizon) must be finite, not NaN.
    #[test]
    fn orthographic_inv_on_unit_circle_boundary_finite() {
        // Point on the horizon: rho == 1
        let (lon, lat) = orthographic_inv(1.0, 0.0);
        // rho == 1 exactly; spec says rho > 1 → NaN; rho == 1 → should be finite
        assert!(
            lon.is_finite() && lat.is_finite(),
            "orthographic inverse: rho=1 (horizon) should be finite, got ({lon}, {lat})"
        );
    }

    // ── Natural Earth: pole behavior ──────────────────────────────────────────

    /// Natural Earth at the North Pole (lat=90°) must produce finite output.
    #[test]
    fn natural_earth_north_pole_finite() {
        let (x, y) = natural_earth_fwd(0.0, 90.0);
        assert!(x.is_finite(), "natural-earth x at north pole: {x}");
        assert!(y.is_finite(), "natural-earth y at north pole: {y}");
    }

    /// Natural Earth x should be 0 when lon=0 regardless of latitude.
    #[test]
    fn natural_earth_zero_lon_gives_zero_x() {
        for lat in [-90.0, -60.0, 0.0, 60.0, 90.0] {
            let (x, _) = natural_earth_fwd(0.0, lat);
            assert!(
                x.abs() < 1e-14,
                "natural-earth: lon=0 should give x=0 at lat={lat}, got x={x}"
            );
        }
    }

    /// Natural Earth round-trip at high latitude (lat=80°).
    // BUG: Newton-Raphson inverse uses wrong Jacobian — derivative is ne_poly(NE_B, phi)
    // but should be ne_poly(NE_B, phi) + phi * d/dphi[ne_poly(NE_B, phi)]; at high
    // latitudes (phi large) the missing term causes lon error ~2.4e-4° (round-trip gives
    // 59.99976 instead of 60.0, error > 1e-6 tolerance).
    #[test]
    fn natural_earth_high_latitude_round_trip() {
        let lon = 60.0_f64;
        let lat = 80.0_f64;
        let (x, y) = natural_earth_fwd(lon, lat);
        assert!(x.is_finite() && y.is_finite());
        let (lon2, lat2) = natural_earth_inv(x, y);
        assert!(
            (lon2 - lon).abs() < 1e-6,
            "natural-earth high-lat lon round-trip: {lon} → {lon2}"
        );
        assert!(
            (lat2 - lat).abs() < 1e-6,
            "natural-earth high-lat lat round-trip: {lat} → {lat2}"
        );
    }

    // ── Albers USA: sub-region routing ────────────────────────────────────────

    /// Albers USA: Alaska coordinates (e.g. Fairbanks) must route to Alaska sub-conic.
    /// The Alaska inset applies a 0.35 scale + offset; continental result would differ.
    #[test]
    fn albers_usa_alaska_routing_differs_from_continental() {
        let alaska_lon = -147.72; // Fairbanks AK
        let alaska_lat = 64.84;
        let (ax, ay) = albers_usa_fwd(alaska_lon, alaska_lat);
        // Alaska branch: ax = conic_x*0.35 - 2.0, so x must be < -1.5 roughly
        // Continental branch would give a very different x (much larger / different sign)
        let (cx, cy) = albers_conic_fwd(alaska_lon, alaska_lat, 29.5, 45.5, 38.0, -96.0);
        assert!(
            (ax - cx).abs() > 0.1,
            "Alaska should route to inset conic, not continental: ax={ax}, cx={cx}"
        );
        assert!(ax.is_finite() && ay.is_finite(), "Alaska inset result must be finite");
    }

    /// Albers USA: Hawaii coordinates (e.g. Honolulu) must route to Hawaii sub-conic.
    #[test]
    fn albers_usa_hawaii_routing_differs_from_continental() {
        let hawaii_lon = -157.82; // Honolulu
        let hawaii_lat = 21.31;
        // Must satisfy: lat < 24.0, lat > 18.0, lon < -154.0
        assert!(hawaii_lat < 24.0 && hawaii_lat > 18.0 && hawaii_lon < -154.0);
        let (hx, hy) = albers_usa_fwd(hawaii_lon, hawaii_lat);
        let (cx, cy) = albers_conic_fwd(hawaii_lon, hawaii_lat, 29.5, 45.5, 38.0, -96.0);
        // Hawaii branch offsets by +0.4, -1.3 — output should differ from continental
        assert!(
            (hx - cx).abs() > 0.01,
            "Hawaii should route to inset conic, not continental: hx={hx}, cx={cx}"
        );
        assert!(hx.is_finite() && hy.is_finite(), "Hawaii inset result must be finite");
    }

    /// Albers USA continental: result for CONUS coordinate is finite.
    #[test]
    fn albers_usa_continental_result_is_finite() {
        // Chicago: lat=41.8, lon=-87.6 (typical CONUS)
        let (x, y) = albers_usa_fwd(-87.6, 41.8);
        assert!(x.is_finite() && y.is_finite(), "CONUS point must project finitely: ({x}, {y})");
    }

    // ── Albers conic: negative discriminant guard ─────────────────────────────

    /// Albers conic: when c - 2*n*phi.sin() < 0, max(0,_) guard must prevent NaN/panic.
    #[test]
    fn albers_conic_extreme_lat_no_panic() {
        // lat=90° pushes phi.sin()→1.0; test that max(0.0) guard prevents sqrt of negative
        let (x, y) = albers_conic_fwd(0.0, 90.0, 29.5, 45.5, 38.0, -96.0);
        assert!(x.is_finite() && y.is_finite(),
            "albers conic at lat=90 must be finite (max(0) guard), got ({x}, {y})");
    }

    // ── Mercator: clamped-pole round-trip consistency ─────────────────────────

    /// Mercator: projecting lat=90 then inverting should give back exactly the clamped lat.
    #[test]
    fn mercator_clamped_pole_inv_gives_clamp_lat() {
        let clamp_lat = 85.051_129_34_f64;
        let (x, y) = mercator_fwd(10.0, 90.0); // triggers clamping
        let (_, lat2) = mercator_inv(x, y);
        assert!(
            (lat2 - clamp_lat).abs() < 1e-6,
            "mercator inverse of clamped north should give clamp_lat={clamp_lat}, got {lat2}"
        );
    }
}
